script:
situation_toxify_world = {
	picture = GFX_evt_georadiation_bell
	complete_icon_frame = GFX_situation_outcome_frame_green
	complete_icon = GFX_toxify_world_outcome
	situation_log_category = developments

	on_monthly = {
		events = {
			extreme_frontiers.2000
		}
	}
	on_progress_complete = {
		custom_tooltip = toxify_world_outcome
		hidden_effect = {
			if = {
				limit = {
					owner = {
						NOT = { has_country_flag = georadiation_first_use }
					}
				}
				situation_event = { id = extreme_frontiers.2005 } # first use
			}
			else = {
				situation_event = { id = extreme_frontiers.2010 } # subsequent uses
			}
		}
		set_situation_locked = yes
	}
	on_abort = {
		target = {
			remove_carrier_flag = toxifying_planet
		}
	}

	stages = {
		stage_1 = {
			icon = GFX_situation_stage_1
			icon_background = GFX_situation_stage_frame_blue
			end = 1000
			custom_tooltip = toxify_world_stage_effects
		}
	}

	approach = {
		name = approach_toxify_world_georadiation
		icon = GFX_situation_approach_radioactive
		icon_background = GFX_situation_approach_bg_green
		on_select = {
			custom_tooltip = approach_toxify_world_georadiation_tt
		}
		default = yes
		resources = {
			category = situations
			upkeep = {
				sr_dark_matter = 1
				rare_crystals = 2
			}
		}
	}
	approach = {
		name = approach_toxify_world_killswitch
		icon = GFX_situation_approach_suspicious
		icon_background = GFX_situation_approach_bg_yellow
		on_select = {
			custom_tooltip = approach_toxify_world_killswitch_tt
			abort_situation = this
		}
		resources = {
			category = situations
			cost = {
				unity = 1000
			}
		}
	}

	abort_trigger = {
		OR = {
			NOT = { exists = target.space_owner }
			target.space_owner = { NOT = { is_same_value = root.owner } }
		}
	}

	monthly_progress = {
		base = 0
		modifier = {
			add = 10
			desc = string_toxification_progress
		}
	}
}
